"""Les sept leçons de « Théorie Scratch » (7e année). Gabarit identique pour chaque leçon (voir theorie.py) :
accroche, comparaison de la vie courante, rappel, l'essentiel en deux phrases, image, activités interactives, vocabulaire arabe / français / anglais,
erreurs fréquentes, « À retenir », « Teste-toi » (5 questions) et activités liées. Chaque texte est un couple (français, arabe)."""
from theorie_core import *

LRI, PDI = "⁦", "⁩"
def ltr(s): return LRI + s + PDI          # isole un nombre ou un couple de nombres (signe moins) dans une phrase arabe

# familles de blocs (pour les questions de la leçon 3)
FAM = {"mv": ("Mouvement", "الحركة"), "lk": ("Apparence", "المظهر"), "sn": ("Son", "الصوت"), "ev": ("Événements", "الأحداث"), "ct": ("Contrôle", "التحكم"),
       "se": ("Capteurs", "الاستشعار"), "op": ("Opérateurs", "العمليات"), "va": ("Variables", "المتغيرات"), "my": ("Mes blocs", "كتلي")}
def fam_q(blk, key, others):
    """« Dans quelle famille est ce bloc ? » : la bonne famille et trois autres"""
    return QZ(("Dans quelle famille se trouve ce bloc ?", "في أي فئة توجد هذه الكتلة؟"), [FAM[key]] + [FAM[o] for o in others], 0, blk=blk)

ROBOT = [fwd(), fwd(), right(), fwd(), fwd(), left(), fwd()]
SQUARE = [flag(), pen_down(), repeat(4, [move(100), turn_r(90)])]
SCRIPT4 = [flag(), move(100), turn_r(90), move(60), say_for("Arrivé !", "وصلت!", 2)]

